<script setup>
import { reactive } from 'vue'
import { ElMessage } from 'element-plus'
import { usePlatformStore } from '@/stores/platform'
const store=usePlatformStore();const form=reactive({...store.params});function save(){if(!store.capabilities.systemSettings)return ElMessage.warning('当前数据库没有系统参数表，暂时无法持久化这些配置');store.saveParams({...form});ElMessage.success('系统参数已保存')}
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">系统参数</h1><p class="page-subtitle">维护告警判定、默认阈值和控制指令可靠性参数。</p></div><div class="page-actions"><el-button type="primary" :disabled="!store.capabilities.systemSettings" @click="save">保存修改</el-button></div></div><el-alert v-if="!store.capabilities.systemSettings" title="当前数据库未定义系统参数表" description="以下参数不能可靠持久化，需后端补充 system_config 表或配置中心接口后再开放保存。" type="warning" show-icon :closable="false" class="schema-warning"/><section class="settings-grid"><div class="content-panel"><div class="section-head"><div><h3>湿度阈值范围</h3><p>限制农户可配置的合理范围</p></div></div><el-form label-position="top"><div class="form-grid"><el-form-item label="允许最小值（%）"><el-input-number v-model="form.humidityMin" :min="0" :max="100"/></el-form-item><el-form-item label="允许最大值（%）"><el-input-number v-model="form.humidityMax" :min="0" :max="100"/></el-form-item></div><el-form-item label="默认土壤湿度下限（%）"><el-slider v-model="form.defaultHumidity" :min="form.humidityMin" :max="form.humidityMax" show-input/></el-form-item></el-form></div><div class="content-panel"><div class="section-head"><div><h3>设备和数据判定</h3><p>根据心跳和数据时间识别异常</p></div></div><el-form label-position="top"><el-form-item label="设备离线判定时间（分钟）"><el-input-number v-model="form.offlineMinutes" :min="1" :max="180"/></el-form-item><el-form-item label="数据未更新判定时间（分钟）"><el-input-number v-model="form.staleDataMinutes" :min="1" :max="180"/></el-form-item><el-form-item label="告警冷却时间（分钟）"><el-input-number v-model="form.alertCooldown" :min="1" :max="240"/></el-form-item></el-form></div><div class="content-panel"><div class="section-head"><div><h3>灌溉安全参数</h3><p>限制运行时长并避免重复控制</p></div></div><el-form label-position="top"><el-form-item label="默认灌溉时长上限（分钟）"><el-input-number v-model="form.irrigationMaxMinutes" :min="5" :max="240"/></el-form-item><el-form-item label="超时后自动关闭"><el-switch :model-value="true" active-text="已启用"/></el-form-item></el-form></div><div class="content-panel"><div class="section-head"><div><h3>控制指令可靠性</h3><p>唯一 commandId、超时和有限重试</p></div></div><el-form label-position="top"><el-form-item label="指令结果等待时间（秒）"><el-input-number v-model="form.commandTimeoutSeconds" :min="3" :max="60"/></el-form-item><el-form-item label="失败重试次数"><el-input-number v-model="form.commandRetryCount" :min="0" :max="5"/></el-form-item><el-alert title="设备端必须按 commandId 进行幂等处理，避免重复开关灌溉设备。" type="info" :closable="false"/></el-form></div></section></div></template>
